namespace LowlandTech.Core;

/// <summary>
/// Canonical paged-list response shape. List endpoints generated by pluginize
/// for CRUD-shaped slices return <c>PagedResult&lt;TDto&gt;</c>: the items for
/// the requested page plus the global total count for prev/next + page-size
/// math on the client. SPEC2300.US04.SC30 Sprint C.
/// </summary>
public record PagedResult<T>(IReadOnlyList<T> Items, int TotalCount);
